// Hebrew (he) PropertyTypeLocale blocks live in a separate JSON (generated by
// scripts/translate-ptp-he.ts) and are attached here at module load to keep the
// main table readable. Falls back to English in page.tsx if a slug is missing.
import ptpHe from "./ptp-he.json";
for (const page of PROPERTY_TYPE_PAGES) {
  const he = (ptpHe as Record<string, PropertyTypeLocale>)[page.slug];
  if (he) page.he = he;
}

export function findPropertyTypePage(slug: string): PropertyTypePage | undefined {
  return PROPERTY_TYPE_PAGES.find(p => p.slug === slug);
}
